<section class="fuel-panel ua-history" aria-labelledby="activity-history-title">
    <div class="fuel-panel-head ua-history-head">
        <h2 id="activity-history-title"><i class="bi bi-list-ul" aria-hidden="true"></i> Recent activity</h2>
        <div class="ua-history-tools"><label class="ua-search" for="activity-search"><i class="bi bi-search" aria-hidden="true"></i><span class="visually-hidden">Search user, module, or record ID</span><input id="activity-search" name="search" type="search" form="activity-filters" value="{{ $filters['search'] ?? '' }}" placeholder="Search activity…" maxlength="100"></label><button type="button" class="fuel-button fuel-button-small" id="activity-refresh"><i class="bi bi-arrow-clockwise" aria-hidden="true"></i> Refresh</button></div>
    </div>
    <div class="ua-table-wrap"><table class="table" id="activity-history-table"><thead><tr><th>When</th><th>User</th><th>Module</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody id="activity-history-rows"><tr><td colspan="6" class="ua-empty">Loading activity…</td></tr></tbody></table></div>
    <div class="ua-pagination"><div class="ua-page-summary"><span id="activity-page-info" role="status" aria-live="polite"></span><span id="activity-updated"></span></div><nav class="ua-page-controls" aria-label="Activity pages"><button type="button" class="ua-page-button" id="activity-previous" aria-label="Previous page" disabled><i class="bi bi-chevron-left" aria-hidden="true"></i></button><span id="activity-page-numbers"></span><button type="button" class="ua-page-button" id="activity-next" aria-label="Next page" disabled><i class="bi bi-chevron-right" aria-hidden="true"></i></button></nav></div>
</section>
